'GST 12 percent', 'gst-12' ), 'rates' => array( array( 'country_code' => 'IN', 'rate' => 12, 'name' => 'GST 12 percent' ) ) ), array( 'class' => array( 'GST 18 percent', 'gst-18' ), 'rates' => array( array( 'country_code' => 'IN', 'rate' => 18, 'name' => 'GST 18 percent' ) ) ) ), 'products' => array( array( 'name' => 'Paracetamol 500mg', 'price' => 2.00, 'category' => 'OTC', 'tax_class' => 'GST 5 percent' ), array( 'name' => 'Vitamin C Tablet', 'price' => 5.00, 'category' => 'Wellness', 'tax_class' => 'GST 12 percent' ), array( 'name' => 'Hand Sanitizer', 'price' => 3.50, 'category' => 'Personal Care', 'tax_class' => 'GST 18 percent' ) ) ), 'supermarket' => array( 'label' => 'Supermarket and Grocery', 'description' => 'Grocery and convenience. EAN barcodes with VAT.', 'settings' => array( 'tax_country' => 'GB', 'tax_inclusive' => 1, 'track_stock' => 1, 'barcode_symbology' => 'EAN13', 'paper_width' => '80mm', 'low_stock_threshold' => 10 ), 'categories' => array( 'Groceries', 'Produce', 'Dairy', 'Bakery', 'Beverages', 'Household' ), 'tax' => array( array( 'class' => array( 'VAT Standard', 'vat-std' ), 'rates' => array( array( 'country_code' => 'GB', 'rate' => 20, 'name' => 'VAT 20 percent' ) ) ), array( 'class' => array( 'VAT Zero', 'vat-zero' ), 'rates' => array( array( 'country_code' => 'GB', 'rate' => 0, 'name' => 'VAT 0 percent' ) ) ) ), 'products' => array( array( 'name' => 'Milk 1L', 'price' => 1.20, 'category' => 'Dairy', 'tax_class' => 'VAT Standard' ), array( 'name' => 'Bread', 'price' => 1.00, 'category' => 'Bakery', 'tax_class' => 'VAT Standard' ), array( 'name' => 'Bananas kg', 'price' => 1.50, 'category' => 'Produce', 'tax_class' => 'VAT Zero' ) ) ), 'other' => array( 'label' => 'Other or Custom', 'description' => 'Start blank and configure everything yourself.', 'settings' => array(), 'categories' => array(), 'tax' => array(), 'products' => array() ) ); } 
public static function apply( $slug ) { $verticals = self::get_verticals(); if ( empty( $verticals[ $slug ] ) ) { return new WP_Error( 'pos_unknown_vertical', 'Unknown business type.' ); } $v = $verticals[ $slug ]; if ( ! empty( $v['settings'] ) ) { Simple_POS_Settings::update( $v['settings'] ); } $cat_ids = array(); foreach ( $v['categories'] as $cat ) { $cat_ids[ $cat ] = self::get_or_create_category( $cat ); } $class_ids = array(); foreach ( $v['tax'] as $tc ) { [ $name, $slug_c ] = $tc['class']; $class_id = self::get_or_create_tax_class( $name, $slug_c ); if ( ! $class_id ) { continue; } $class_ids[ $name ] = $class_id; foreach ( $tc['rates'] as $rate ) { self::create_rate_once( $class_id, $rate ); } } foreach ( $v['products'] as $p ) { if ( self::product_exists( $p['name'] ) ) { continue; } $cat_id = isset( $p['category'], $cat_ids[ $p['category'] ] ) ? $cat_ids[ $p['category'] ] : null; $tax_class = isset( $p['tax_class'], $class_ids[ $p['tax_class'] ] ) ? $class_ids[ $p['tax_class'] ] : 0; $track = isset( $p['track_stock'] ) ? (int) $p['track_stock'] : 1; Simple_POS_Products::create_product( array( 'name' => $p['name'], 'category_id' => $cat_id, 'price' => $p['price'], 'tax_class_id' => $tax_class, 'track_stock' => $track, 'status' => 'active' ) ); } update_option( 'simple_pos_vertical', $slug ); return true; } 
private static function get_or_create_category( $name ) { $cats = Simple_POS_Products::get_categories(); foreach ( $cats as $c ) { if ( strcasecmp( $c->name, $name ) === 0 ) { return (int) $c->id; } } $id = Simple_POS_Products::create_category( $name ); return is_int( $id ) ? $id : 0; } private static function get_or_create_tax_class( $name, $slug_c ) { $classes = Simple_POS_Tax::get_classes(); foreach ( $classes as $c ) { if ( $c->slug === $slug_c or strcasecmp( $c->name, $name ) === 0 ) { return (int) $c->id; } } $id = Simple_POS_Tax::create_class( $name, '' ); return is_int( $id ) ? $id : 0; } private static function create_rate_once( $class_id, $rate ) { $rates = Simple_POS_Tax::get_rates( $class_id ); foreach ( $rates as $r ) { if ( $r->country_code === $rate['country_code'] and strtoupper( (string) ( $r->state_code ?: '' ) ) === strtoupper( (string) ( $rate['state_code'] ?? '' ) ) and (int) $r->priority === (int) ( $rate['priority'] ?? 0 ) and (float) $r->rate === (float) $rate['rate'] ) { return; } } $rate['class_id'] = $class_id; Simple_POS_Tax::create_rate( $rate ); } private static function product_exists( $name ) { $res = Simple_POS_Products::get_products( array( 'search' => $name, 'per_page' => 1 ) ); if ( empty( $res['items'] ) ) { return false; } foreach ( $res['items'] as $p ) { if ( strcasecmp( $p->name, $name ) === 0 ) { return true; } } return false; } } 
